# ===============================================================================
# TEST 2: Run Small Simulation
# ===============================================================================

cat("TEST 2: Running small simulation...\n")

# Simple correlation matrix
test_corr <- matrix(c(
  1.0, 0.3,
  0.3, 1.0
), nrow = 2, byrow = TRUE)

# Run minimal simulation
test_results <- tryCatch({
  run_general_simulation(
    data_generation = list(
      method = "joint_mvn",
      params = list(
        correlation_matrix = test_corr,
        mean_vector = c(0, 0)
      )
    ),
    predictor_config = list(
      names = c("x1", "x2"),
      types = c("continuous", "continuous"),
      effects = list(
        fixed = c(0.5, -0.3),
        residual_sd = 1.0
      )
    ),
    reference_model = "lm",
    target_models = c("lm"),
    sample_sizes = c(50, 100),  # Just 2 sample sizes for testing
    n_simulations = 10,  # Very few simulations for quick test
    metrics = c("mse", "r_squared"),
    efficiency_threshold = 0.95,
    cv_folds = 2,
    cv_repeats = 1,
    seed = 123,
    output_path = NULL,  # Don't save
    verbose = FALSE
  )
}, error = function(e) {
  cat("  ✗ Simulation failed with error:", e$message, "\n")
  NULL
})

if (!is.null(test_results)) {
  cat("  ✓ Simulation completed successfully\n")
  cat("  ✓ Results structure:", class(test_results), "\n")
  cat("  ✓ Found", length(test_results$results), "model(s)\n")
  cat("  ✓ Found", length(test_results$results$lm), "metric(s)\n\n")
} else {
  stop("Simulation test failed")
}

