# Test data generation
test_data <- generate_mvn_data(
  n = 50,
  params = list(
    correlation_matrix = test_corr,
    mean_vector = c(0, 0)
  ),
  predictor_config = list(
    names = c("x1", "x2"),
    types = c("continuous", "continuous"),
    effects = list(
      fixed = c(0.5, -0.3),
      residual_sd = 1.0
    )
  ),
  reference_model = "lm"
)
if (is.data.frame(test_data) && nrow(test_data) == 50 && "y" %in% names(test_data)) {
  cat("  ✓ Data generation works\n")
} else {
  cat("  ✗ Data generation failed\n")
}

# Test model fitting
test_model <- fit_model(
  model_type = "lm",
  formula_obj = y ~ x1 + x2,
  data = test_data
)
if (inherits(test_model, "lm")) {
  cat("  ✓ Model fitting works\n")
} else {
  cat("  ✗ Model fitting failed\n")
}

# Test prediction
test_preds <- predict_model(
  model = test_model,
  model_type = "lm",
  newdata = test_data
)
if (is.numeric(test_preds) && length(test_preds) == nrow(test_data)) {
  cat("  ✓ Prediction works\n")
} else {
  cat("  ✗ Prediction failed\n")
}

# Test metrics calculation
test_metrics <- calculate_metrics(
  y_true = test_data$y,
  y_pred = test_preds,
  metrics = c("mse", "r_squared")
)
if (is.list(test_metrics) && "mse" %in% names(test_metrics) && "r_squared" %in% names(test_metrics)) {
  cat("  ✓ Metrics calculation works\n")
  cat("    - MSE:", round(test_metrics$mse, 4), "\n")
  cat("    - R²:", round(test_metrics$r_squared, 4), "\n")
} else {
  cat("  ✗ Metrics calculation failed\n")
}

